-- -------------------------------------------------------------------------
-- Self-check. Any failure raises and rolls the whole file back.
-- -------------------------------------------------------------------------
do $$
declare
  v_expected constant integer := 197;
  v_actual   integer;
  v_bad      integer;
begin
  select count(*) into v_actual from public.areas;
  if v_actual < floor(v_expected * 0.9) or v_actual > ceil(v_expected * 1.1) then
    raise exception 'PHASE78 SEED SELF-CHECK FAIL (a): public.areas holds % row(s), expected % within 10%%', v_actual, v_expected;
  end if;

  select count(*) into v_bad from public.areas
   where min_lat >= max_lat or min_lng >= max_lng;
  if v_bad > 0 then
    raise exception 'PHASE78 SEED SELF-CHECK FAIL (b): % row(s) carry an inconsistent bounding box', v_bad;
  end if;

  raise notice 'PHASE78 SEED SELF-CHECK PASS: % row(s), every bounding box self-consistent', v_actual;
end $$;

commit;
